@SpecCompliant(spec = "draft-ietf-xmpp-3920bis-22", section = "10.4.3", status = SpecCompliant.ComplianceStatus.FINISHED, coverage = SpecCompliant.ComplianceCoverage.COMPLETE)
public void smartDeliveryException() throws Exception {
    Stanza stanza = StanzaBuilder.createMessageStanza(FROM, TO, LANG, BODY).build();
    strategy.process(stanza, Arrays.asList((DeliveryException) new RemoteServerNotFoundException(ERROR_TEXT)));
    Stanza expected = StanzaBuilder.createMessageStanza(SERVER, FROM, MessageStanzaType.ERROR, null, BODY).startInnerElement("error", NamespaceURIs.JABBER_CLIENT).addAttribute("type", "cancel").startInnerElement("remote-server-not-found", NamespaceURIs.URN_IETF_PARAMS_XML_NS_XMPP_STANZAS).endInnerElement().startInnerElement("text", NamespaceURIs.URN_IETF_PARAMS_XML_NS_XMPP_STANZAS).addAttribute(NamespaceURIs.XML, "lang", "en").addText(ERROR_TEXT).endInnerElement().build();
    ArgumentCaptor<Stanza> stanzaCaptor = ArgumentCaptor.forClass(Stanza.class);
    verify(stanzaBroker).write(eq(FROM), stanzaCaptor.capture(), eq(IgnoreFailureStrategy.INSTANCE));
    StanzaAssert.assertEquals(expected, stanzaCaptor.getValue());
}

@Test
public void noException() throws Exception {
    Stanza stanza = StanzaBuilder.createMessageStanza(FROM, TO, LANG, BODY).build();
    strategy.process(stanza, null);
    Stanza expected = StanzaBuilder.createMessageStanza(SERVER, FROM, MessageStanzaType.ERROR, null, BODY).startInnerElement("error", NamespaceURIs.JABBER_CLIENT).addAttribute("type", "cancel").startInnerElement("service-unavailable", NamespaceURIs.URN_IETF_PARAMS_XML_NS_XMPP_STANZAS).endInnerElement().startInnerElement("text", NamespaceURIs.URN_IETF_PARAMS_XML_NS_XMPP_STANZAS).addAttribute(NamespaceURIs.XML, "lang", "en").addText("stanza could not be delivered").endInnerElement().build();
    ArgumentCaptor<Stanza> stanzaCaptor = ArgumentCaptor.forClass(Stanza.class);
    verify(stanzaBroker).write(eq(FROM), stanzaCaptor.capture(), eq(IgnoreFailureStrategy.INSTANCE));
    StanzaAssert.assertEquals(expected, stanzaCaptor.getValue());
}

