    // <iq type='result' id='reg1'>
    // <query xmlns='jabber:iq:register'>
    // <instructions>
    // Choose a username and password for use with this service.
    // Please also provide your email address.
    // </instructions>
    // <username/>
    // <password/>
    // <email/>
