    Assert.assertEquals("1", response.getAttributeValue("id"));
    XMLElement time = response.getSingleInnerElementsNamed("time", NamespaceURIs.URN_XMPP_TIME);
    Assert.assertEquals(2, time.getInnerElements().size());
